def split_single_wheels(apps, schema_editor):
    SingleWheel = apps.get_model('components', 'SingleWheel')
    FrontSingleWheel = apps.get_model('components', 'FrontSingleWheel')
    RearWheel = apps.get_model('components', 'RearWheel')
    Components = apps.get_model('components', 'Components')

    for wheel in SingleWheel.objects.all():
        shared = dict(
            components_ptr_id=wheel.pk,
            wheel_size=wheel.wheel_size,
            max_tire_width_mm=wheel.max_tire_width_mm,
            hub_spacing=wheel.hub_spacing,
        )
        if wheel.position == 'front':
            FrontSingleWheel(**shared).save_base(raw=True)
            Components.objects.filter(pk=wheel.pk).update(component_type='front_wheel')
            continue
        RearWheel(
            **shared,
            threading=wheel.threading,
            hub_type=wheel.hub_type,
            cog_interface=wheel.cog_interface,
        ).save_base(raw=True)
        Components.objects.filter(pk=wheel.pk).update(component_type='rear_wheel')


